(* [comment removed for export] *)
Lemma art_ghost_cls_pop : forall c0 cl0, 1 <= c0 <= 30 -> art_cls_ok c0 cl0 ->
  (0 < cl_au cl0 -> 262144 <= cl_mfa cl0) -> Z.of_nat (length (cl_cache cl0)) <= art_ic_mc c0 ->
