Lemma art_mrep_out_class : forall c0 x, 1 <= c0 <= 30 -> c0 <> c ->
  (rn_spb rn + c0 * 2 ^ 32 <= U x < rn_spb rn + c0 * 2 ^ 32 + 2 ^ 32
