Lemma art_mrep_eq_chunk : forall w0 a, art_cptr_ok sz (cl_au cl) w0 -> w0 <> w ->
  (rn_spb rn + c * 2 ^ 32 + 16 * w0 <= a < rn_spb rn + c * 2 ^ 32 + 16 * w0 + sz
