(* [comment removed for export] *)
Lemma art_mrep_block_cases : forall b, In b LB ->
  (exists c0 w0, 1 <= c0 <= 30 /\ art_cptr_ok (AsanTab.class_size c0) (cl_au (g_cls FSG G c0)) w0 /\ (c0 = c -> w0 <> w) /\ 1 <= snd b
